        <p style="color: #00ff88; font-size: 20px; text-shadow: 0 0 10px #00ff88; animation: pulse 1.5s infinite;">
          PRESS SPACE OR A BUTTON TO START
        </p>
      </div>
    `;
    container.appendChild(startScreen);
