        </p>
      </div>
    `;
    container.appendChild(victoryScreen);
    this.victoryScreen = victoryScreen;

    // Add CSS animation for pulsing text
    const style = document.createElement('style');
    style.textContent = `@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }`;
    document.head.appendChild(style);
  }

  update(score, lives, wave) {
    if (this.scoreEl) this.scoreEl.textContent = score.toString();
    if (this.livesEl) this.livesEl.textContent = lives.toString();
    if (this.waveEl) this.waveEl.textContent = wave.toString();
  }

  showPowerUp(type, duration) {
    const names = { spread: 'SPREAD SHOT', rapid: 'RAPID FIRE', shield: 'SHIELD' };
    const colors = { spread: '#ffff00', rapid: '#ff8800', shield: '#00ffff' };
    if (this.powerUpEl) {
      this.powerUpEl.innerHTML = `
        <div style="background: rgba(10, 10, 30, 0.8); backdrop-filter: blur(12px); border: 1px solid ${colors[type]}44;
                    border-radius: 8px; padding: 8px 20px;">
          <span style="color: ${colors[type]}; font-size: 16px; text-shadow: 0 0 10px ${colors[type]};">
            ${names[type]} — ${duration.toFixed(1)}s
          </span>
        </div>`;
    }
  }

  hidePowerUp() {
    if (this.powerUpEl) this.powerUpEl.innerHTML = '';
  }

  showStartScreen() {
    if (this.startScreen) this.startScreen.style.display = 'flex';
    if (this.gameOverScreen) this.gameOverScreen.style.display = 'none';
    if (this.victoryScreen) this.victoryScreen.style.display = 'none';
  }

  hideStartScreen() {
    if (this.startScreen) this.startScreen.style.display = 'none';
  }

  showGameOver(finalScore) {
    if (this.gameOverScreen) {
      this.gameOverScreen.style.display = 'flex';
      const scoreEl = this.gameOverScreen.querySelector('#final-score');
      if (scoreEl) scoreEl.textContent = `SCORE: ${finalScore}`;
    }
  }

  showVictory(finalScore, waveReached) {
    if (this.victoryScreen) {
      this.victoryScreen.style.display = 'flex';
      const scoreEl = this.victoryScreen.querySelector('#victory-score');
      if (scoreEl) scoreEl.textContent = `SCORE: ${finalScore} — WAVE ${waveReached}`;
    }
  }

  hideAllScreens() {
    if (this.startScreen) this.startScreen.style.display = 'none';
    if (this.gameOverScreen) this.gameOverScreen.style.display = 'none';
    if (this.victoryScreen) this.victoryScreen.style.display = 'none';
  }

  destroy() {
    // Remove HUD elements from DOM
    const hud = document.getElementById('game-hud');
    if (hud) hud.remove();
    const startScreen = document.getElementById('start-screen');
    if (startScreen) startScreen.remove();
    const gameOverScreen = document.getElementById('game-over-screen');
    if (gameOverScreen) gameOverScreen.remove();
    const victoryScreen = document.getElementById('victory-screen');
    if (victoryScreen) victoryScreen.remove();
  }
}

import { MathUtils } from '../../../shared/math/MathUtils.js';

export class Physics {
  static checkAABB(a, b) {
    const axMin = a.position.x - (a.userData.width || 0.5) / 2;
    const axMax = a.position.x + (a.userData.width || 0.5) / 2;
    const ayMin = a.position.y - (a.userData.height || 0.3) / 2;
    const ayMax = a.position.y + (a.userData.height || 0.3) / 2;

    const bxMin = b.position.x - (b.userData.width || 0.5) / 2;
    const bxMax = b.position.x + (b.userData.width || 0.5) / 2;
    const byMin = b.position.y - (b.userData.height || 0.3) / 2;
    const byMax = b.position.y + (b.userData.height || 0.3) / 2;

    return axMin < bxMax && axMax > bxMin && ayMin < byMax && ayMax > byMin;
  }

  static checkProjectileHit(projectile, targets) {
    const hits = [];
    if (!projectile.isActive()) return hits;

    for (let i = 0; i < targets.length; i++) {
      const target = targets[i];
      if (!target || !target.getMesh() || !target.getMesh().visible) continue;

      if (this.checkAABB(projectile, target)) {
        hits.push({ projectile, target });
        break;
      }
    }
    return hits;
  }

  static checkAlienReachedBottom(alienPositions, playerY) {
    for (let i = 0; i < alienPositions.length; i++) {
      if (alienPositions[i].y <= playerY + 1.5) {
        return true;
      }
    }
    return false;
  }

  static checkBarrierCollision(projectile, barriers) {
    if (!projectile.isActive()) return null;

    for (let i = 0; i < barriers.length; i++) {
      const barrier = barriers[i];
      if (barrier.isFullyDestroyed()) continue;

      const blocks = barrier.getBlocks();
      for (let j = 0; j < blocks.length; j++) {
        const block = blocks[j];
        if (!block.visible) continue;

        if (this.checkAABB(projectile, block)) {
          return { barrier, blockIndex: j };
        }
      }
    }
    return null;
  }

  static checkPowerUpCollision(powerUp, player) {
    if (!powerUp.isActive() || !player.getMesh().visible) return false;
    const dist = MathUtils.vec3Distance(powerUp.getMesh().position, player.getMesh().position);
    return dist < 1.0;
  }

  static checkMysteryShipCollision(projectile, mysteryShip) {
    if (!projectile.isActive() || !mysteryShip.isActive()) return false;
    const dist = MathUtils.vec3Distance(projectile.getMesh().position, mysteryShip.getMesh().position);
    return dist < 1.2;
  }

  static clampToRange(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }
}

/**
 * Math utilities for Space Invaders game.
 * Lightweight vector math, interpolation, clamping, and angle normalization.
 */

export function lerp(a, b, t) {
  return a + (b - a) * t;
}

export function clamp(val, min, max) {
  return Math.max(min, Math.min(max, val));
}

export function angleWrap(angle) {
  let a = angle % (Math.PI * 2);
  if (a > Math.PI) a -= Math.PI * 2;
  else if (a < -Math.PI) a += Math.PI * 2;
  return a;
}

export function vec3Lerp(v1, v2, t) {
  return {
    x: lerp(v1.x, v2.x, t),
    y: lerp(v1.y, v2.y, t),
    z: lerp(v1.z, v2.z, t),
  };
}

export function vec3Distance(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  const dz = a.z - b.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

export function dotProduct(a, b) {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}

export function normalizeVec3(v) {
  const len = Math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
  if (len === 0) return { x: 0, y: 0, z: 0 };
  return { x: v.x / len, y: v.y / len, z: v.z / len };
}

export function randomRange(min, max) {
  return min + Math.random() * (max - min);
}

export function randomInt(min, max) {
  return Math.floor(randomRange(min, max + 1));
}

